using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SchoolERP.Domain.Entities;namespace SchoolERP.Infrastructure.Persistence.Configurations;public sealed class ClassSubjectConfiguration:IEntityTypeConfiguration<ClassSubject>{public void Configure(EntityTypeBuilder<ClassSubject>b){b.ToTable("class_subjects",t=>t.HasCheckConstraint("ck_class_subjects_order","display_order >= 0"));b.ConfigureAudit();b.Property(x=>x.TenantId).HasColumnName("tenant_id");b.Property(x=>x.SchoolId).HasColumnName("school_id");b.Property(x=>x.AcademicYearId).HasColumnName("academic_year_id");b.Property(x=>x.SchoolClassId).HasColumnName("school_class_id");b.Property(x=>x.SubjectId).HasColumnName("subject_id");b.Property(x=>x.IsMandatory).HasColumnName("is_mandatory");b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.HasOne(x=>x.School).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.AcademicYear).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.SchoolClass).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.SchoolClassId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Subject).WithMany(x=>x.ClassSubjects).HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.SubjectId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.TenantId);b.HasIndex(x=>x.AcademicYearId);b.HasIndex(x=>x.SchoolClassId);b.HasIndex(x=>x.SubjectId);b.HasIndex(x=>new{x.SchoolClassId,x.SubjectId}).IsUnique().HasDatabaseName("ux_class_subjects_class_subject");}}
